SELECT symbol, id, price, observed_at, UNIX_TIMESTAMP(observed_at) AS obs_epoch, UNIX_TIMESTAMP(source_received_at) AS recv_epoch, delivery_status FROM crypto_ai.market_price_event WHERE symbol='EGLDUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791747600) AND FROM_UNIXTIME(1791747817) ORDER BY observed_at LIMIT 100;
SELECT symbol, id, price, observed_at, UNIX_TIMESTAMP(observed_at) AS obs_epoch, delivery_status FROM crypto_ai.market_price_event WHERE (symbol='EGLDUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791741550) AND FROM_UNIXTIME(1791741613)) OR (symbol='XRPUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791764990) AND FROM_UNIXTIME(1791765007)) OR (symbol='SHIBUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791778500) AND FROM_UNIXTIME(1791778546)) OR (symbol='ACEUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791788690) AND FROM_UNIXTIME(1791788721)) ORDER BY symbol, observed_at LIMIT 120;